import ai.eliza.plugins.notifications.MailHistoryReconciliation;
import java.util.*;
import org.json.*;
public class MailHistoryReconciliationTest {
 static void check(boolean b,String message){if(!b)throw new AssertionError(message);}
 interface Task {void run()throws Exception;}
 static void refuses(Task task)throws Exception{try{task.run();throw new AssertionError("Expected refusal");}catch(AssertionError failure){throw failure;}catch(Exception expected){}}
 static JSONObject binding(String generation)throws Exception{return new JSONObject().put("generation",generation).put("grantId","grant").put("accountRef","owner").put("credentialId","credential").put("userId","owner");}
 static JSONObject event(String rev,String type,String message,String...labels)throws Exception{JSONObject e=new JSONObject().put("id",rev+":"+type+":"+message).put("historyId",rev).put("type",type).put("messageId",message).put("threadId","thread").put("labelIds",new JSONArray(Arrays.asList(labels)));if(type.equals("message-added"))e.put("messageAvailable",true);return e;}
 static JSONObject page(String start,String current,String next,JSONObject...events)throws Exception{return new JSONObject().put("version",1).put("grantId","grant").put("status","page").put("startHistoryId",start).put("historyId",current).put("checkpoint",next==null?current:JSONObject.NULL).put("nextPageToken",next==null?JSONObject.NULL:next).put("events",new JSONArray(Arrays.asList(events))).put("backfillRequired",false);}
 static JSONObject baseline(String current)throws Exception{return new JSONObject().put("version",1).put("grantId","grant").put("status","baseline-required").put("startHistoryId",JSONObject.NULL).put("historyId",current).put("checkpoint",JSONObject.NULL).put("nextPageToken",JSONObject.NULL).put("events",new JSONArray()).put("backfillRequired",true);}
 static class Memory implements MailHistoryReconciliation.Store {String raw;boolean fail;public String read(){return raw;}public void write(String value)throws Exception{if(fail)throw new Exception("storage failure");raw=value;}}
 static class Poster implements MailHistoryReconciliation.Poster {boolean allowed=true,listed=true,fail,denied;int posts;Set<String> active=new HashSet<>();Memory memory;public boolean allowed(){return allowed;}public boolean active(String key){return active.contains(key);}public void cancel(String key){active.remove(key);}public void post(String key){posts++;if(denied)throw new SecurityException("permission lost");if(listed)active.add(key);if(fail)throw new IllegalStateException("process death");}}
 static class Case {Memory memory=new Memory();Poster poster=new Poster();boolean current=true;MailHistoryReconciliation engine;Case()throws Exception{memory.raw=MailHistoryReconciliation.initial(binding("generation-a")).toString();engine=new MailHistoryReconciliation(memory,()->{if(!current)throw new SecurityException("changed");},poster);}JSONObject s()throws Exception{return new JSONObject(memory.raw);}String key()throws Exception{return s().getJSONObject("notices").keys().next();}String phase()throws Exception{return s().getJSONObject("notices").getJSONObject(key()).getString("phase");}void seed()throws Exception{engine.accept(baseline("100"),1);}void mail()throws Exception{engine.accept(page("100","102",null,event("101","message-added","m","INBOX","UNREAD")),2);}}
 public static void main(String[]args)throws Exception{
  Case a=new Case();a.seed();check(a.engine.status().getBoolean("incompleteCatchup"),"baseline is not complete sync");check(a.poster.posts==0,"quiet baseline");
  a.engine.accept(page("100","110","next",event("101","message-added","m","INBOX","UNREAD")),2);check(a.engine.query().getString("startHistoryId").equals("100"),"original watermark held");check(a.engine.query().getString("pageToken").equals("next"),"continuation durable");a.engine.publish();check(a.poster.posts==1&&a.phase().equals("posted"),"notice after durable page");
  a.engine=new MailHistoryReconciliation(a.memory,()->{},a.poster);a.engine.publish();check(a.poster.posts==1,"restart never reposts");a.engine.accept(page("100","112",null,event("111","labels-removed","m","UNREAD")),3);check(a.engine.query().getString("startHistoryId").equals("112"),"final checkpoint");a.engine.publish();check(a.poster.active.isEmpty(),"read mail withdrawn");
  Case b=new Case();b.seed();b.memory.fail=true;refuses(b::mail);check(b.engine.query().getString("startHistoryId").equals("100")&&b.poster.posts==0,"failed write no checkpoint or notice");b.memory.fail=false;b.mail();b.poster.fail=true;refuses(()->b.engine.publish());check(b.phase().equals("dispatching"),"death after notify remains reserved");b.poster.fail=false;b.engine.publish();check(b.phase().equals("posted")&&b.poster.posts==1,"observed interrupted post never repeated");
  Case c=new Case();c.seed();c.mail();c.poster.listed=false;c.engine.publish();check(c.phase().equals("uncertain"),"unlisted notify never claims posted");c.engine.publish();check(c.poster.posts==1,"uncertain not replayed");
  Case d=new Case();d.seed();d.mail();d.poster.allowed=false;d.engine.publish();check(d.phase().equals("denied")&&d.poster.posts==0,"permission denial durable");d.poster.allowed=true;d.engine.publish();check(d.poster.posts==0,"permission change no alert replay");
  Case race=new Case();race.seed();race.mail();race.poster.denied=true;race.engine.publish();check(race.phase().equals("denied"),"revocation after allowed never posted");
  Case owner=new Case();owner.seed();owner.mail();owner.current=false;refuses(()->owner.engine.publish());check(owner.poster.posts==0,"stale owner suppressed");
  Case tap=new Case();tap.seed();tap.mail();tap.engine.publish();String oldKey=tap.key();tap.engine.capture(oldKey);check(tap.engine.pending().has("token"),"current tap retained");String token=tap.engine.pending().getString("token");refuses(()->tap.engine.consume("wrong"));tap.engine.consume(token);check(!tap.engine.pending().has("token"),"tap consumed once");
  tap.memory.raw=MailHistoryReconciliation.initial(binding("generation-b")).toString();tap.seed();tap.mail();tap.engine.publish();check(!oldKey.equals(tap.key()),"A-B-A config changes pending intent identity");tap.engine.capture(oldKey);check(!tap.engine.pending().has("token"),"old intent cannot open new notice");
  Case question=new Case();question.seed();question.mail();question.engine.publish();question.engine.capture(question.key(),true);String questionToken=question.engine.pending().getString("token");check(question.engine.pending().getBoolean("question"),"explicit Ask mode retained");question.memory.fail=true;refuses(()->question.engine.releaseQuestion(questionToken));question.memory.fail=false;check(question.engine.pending().has("token"),"failed cancel retains question");question.engine.releaseQuestion(questionToken);check(!question.engine.pending().has("token")&&question.poster.active.contains(question.key()),"cancel preserves reusable notice");question.engine.capture(question.key(),true);question.poster.active.clear();check(!question.engine.pending().has("token"),"withdrawn OS notice cannot authorize Ask");
  Case expired=new Case();expired.seed();JSONObject reset=baseline("200").put("status","reset-required").put("startHistoryId","100").put("historyId",JSONObject.NULL);expired.engine.accept(reset,5);check(expired.engine.query().isNull("startHistoryId"),"expired requests fresh baseline");expired.engine.accept(baseline("300"),6);check(expired.poster.posts==0&&expired.engine.status().getBoolean("incompleteCatchup"),"reset remains quiet and incomplete");
  Case bad=new Case();bad.seed();refuses(()->bad.engine.accept(page("100","101",null,event("101","message-added","m","INBOX","UNREAD")).put("grantId","other"),2));check(bad.engine.query().getString("startHistoryId").equals("100"),"wrong grant no checkpoint");
  JSONObject unhydrated=event("101","message-added","m","INBOX","UNREAD");unhydrated.remove("messageAvailable");refuses(()->bad.engine.accept(page("100","101",null,unhydrated),2));
  bad.engine.accept(page("100","105",null,event("101","message-added","sent","SENT"),event("102","message-added","read","INBOX"),event("103","message-added","spam","INBOX","UNREAD","SPAM"),event("104","message-added","gone").put("messageAvailable",false)),2);bad.engine.publish();check(bad.poster.posts==0,"sent read spam deleted arrivals never notify");
  Case order=new Case();order.seed();order.engine.accept(page("100","110","p",event("105","labels-added","m","UNREAD")),2);refuses(()->order.engine.accept(page("100","110",null,event("104","message-added","m","INBOX","UNREAD")),3));check(order.engine.query().getString("pageToken").equals("p"),"backwards continuation retained");
  Case huge=new Case();huge.engine.accept(baseline("9999999999999999998"),1);huge.engine.accept(page("9999999999999999998","10000000000000000000",null,event("9999999999999999999","message-added","m","INBOX","UNREAD")),2);check(huge.engine.query().getString("startHistoryId").equals("10000000000000000000"),"decimal precision retained");
  Case lifetime=new Case();lifetime.seed();lifetime.poster.allowed=false;
  for(int i=0;i<1100;i++){String start=String.valueOf(100+i),end=String.valueOf(101+i);lifetime.engine.accept(page(start,end,null,event(end,"message-added","m"+i,"INBOX","UNREAD")),i+2);lifetime.engine.publish();}
  check(lifetime.s().getJSONObject("notices").length()==1,"completed notices do not exhaust lifetime ledger");
  Case retain=new Case();retain.seed();retain.mail();retain.engine.accept(page("102","103",null),90000000);check(retain.s().getJSONObject("notices").length()==1,"pending survives pruning");retain.engine.publish();retain.engine.capture(retain.key());retain.poster.active.clear();retain.engine.accept(page("103","104",null),180000000);check(retain.engine.pending().has("token"),"captured expired notice survives pruning");
  System.out.println("PASS mail durable reconciliation, notice uncertainty, owner fences and pagination");
 }
}
